    tcgen05.fence::after_thread_sync;
    and.b32 %r40, %r0, 96;
    shl.b32 %r40, %r40, 16;
    shr.u32 %r41, %r0, 7;
    shl.b32 %r41, %r41, 8;
    add.u32 %r40, %r40, %r41;
    add.u32 %r40, %r40, %r8;
    shl.b32 %r42, %r0, 9;
    and.b32 %r43, %r0, 7;
    shl.b32 %r43, %r43, 4;
    xor.b32 %r42, %r42, %r43;
    add.u32 %r42, %r42, %r3;
    mov.u32 %r44, 0;
